export type Resource =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'ready'; title: string; members: string[] };

export type Props = { resource: Resource; onRetry: () => void };

export function Component({ resource, onRetry }: Props) {
  // status 분기 안에서만 상태별 속성에 접근해 유니언의 타입 좁히기를 유지한다.
  switch (resource.status) {
    case 'idle':
      return <p role="status">Choose a project</p>;

    case 'loading':
      return <p role="status">Loading project</p>;

    case 'error':
      return (
        <section>
          <p role="alert">{resource.message}</p>
          <button type="button" onClick={() => onRetry()}>
            Retry
          </button>
        </section>
      );

    case 'ready':
      return (
        <section>
          <h2>{resource.title}</h2>
          {resource.members.length === 0 ? (
            <p role="status">No members</p>
          ) : (
            <ul aria-label="Members">
              {resource.members.map((member, index) => (
                // 이름 중복을 허용하며 각 항목은 별도 상태가 없는 텍스트다.
                <li key={index}>{member}</li>
              ))}
            </ul>
          )}
        </section>
      );
  }
}
